/** Audit probe: provider disposal must retain writes made by a dependent consumer's teardown. */
import { Context } from '@deepseek-ai/cordis'
import SessionStore, { SessionId, type Session } from '@deepseek-ai/dsh-session'
import JsonlSessionPersistence from '@deepseek-ai/dsh-session-persistence-jsonl'
import { mkdtemp, readFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { scheduler } from 'node:timers/promises'
import { expect, it } from 'vitest'
import { logPath } from '../src/format.ts'

it('persists the final turn event emitted during provider-triggered consumer disposal', async () => {
  const root = await mkdtemp(join(tmpdir(), 'dsh-audit-provider-unload-'))
  const ctx = new Context()
  const entered = Promise.withResolvers<void>()
  const release = Promise.withResolvers<void>()
  let live: Session | undefined
  let unload: Promise<unknown> | undefined
  try {
    await ctx.plugin(SessionStore)
    const provider = await ctx.plugin(JsonlSessionPersistence, { root, compression: 'none' })
    const consumer = {
      name: 'audit-jsonl-consumer',
      inject: ['sessions', 'sessionPersistence'],
      async apply(consumerCtx: Context) {
        const session = ctx.sessions.create(SessionId('audit-jsonl-final-event'))
        live = session
        await consumerCtx.sessionPersistence.create(session.header)
        session.append('turn/start', { turn: 1 })
        await consumerCtx.sessions.flush(session)
        consumerCtx.effect(() => async () => {
          entered.resolve()
          await release.promise
          session.append('turn/end', { turn: 1, reason: { kind: 'completed' } })
        })
      },
    }
    await ctx.plugin(consumer)
    if (live === undefined) throw new Error('audit setup: consumer did not create a Session')
    const session = live
    const path = logPath(root, session.header.cwd, session.id, 'none')
    expect(await readFile(path, 'utf8')).toContain('turn/start')
    unload = provider.dispose()
    await Promise.race([
      entered.promise,
      unload.then(() => { throw new Error('audit setup: provider disposed before dependent entered teardown') }),
    ])
    await scheduler.yield()
    const listenerCount = ctx.events.dispatch('emit', ['session/event']).length
    release.resolve()
    await unload
    const persisted = (await readFile(path, 'utf8')).trim().split('\n').map(line => JSON.parse(line) as { type?: string })
    console.log('AUDIT_JSONL', JSON.stringify({ listenerCountDuringConsumerTeardown: listenerCount,
      liveTypes: session.snapshotEvents().map(event => event.type), persistedTypes: persisted.map(event => event.type) }))
    expect(persisted.some(event => event.type === 'turn/end')).toBe(true)
  } finally {
    release.resolve()
    try { await unload } finally {
      try { await ctx.fiber.dispose() } finally { await rm(root, { recursive: true, force: true }) }
    }
  }
}, 15_000)

/** Audit probe: emulate Chokidar close removing listeners before a late write-settle error. */
import { Context } from '@deepseek-ai/cordis'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { expect, it, vi } from 'vitest'
import { LocalCredentialProvider } from '../src/index.ts'

vi.mock('chokidar', async () => {
  const { EventEmitter } = await import('node:events')
  class Watcher extends EventEmitter {
    close() { this.removeAllListeners(); return Promise.resolve() }
  }
  const instances: Watcher[] = []
  return { watch: () => { const watcher = new Watcher(); instances.push(watcher); return watcher }, __auditInstances: instances }
})

it('contains a late watcher error after close clears listeners', async () => {
  const root = await mkdtemp(join(tmpdir(), 'dsh-audit-watcher-close-'))
  const ctx = new Context()
  try {
    await ctx.plugin(LocalCredentialProvider, { path: join(root, '.credentials.yaml'), debounceMs: 0 })
    const fake = await import('chokidar') as unknown as { __auditInstances: import('node:events').EventEmitter[] }
    expect(fake.__auditInstances).toHaveLength(1)
    const watcher = fake.__auditInstances[0]!
    expect(watcher.listenerCount('error')).toBe(1)
    await ctx.fiber.dispose()
    console.log('AUDIT_WATCHER', JSON.stringify({ errorListenersAfterClose: watcher.listenerCount('error') }))
    expect(() => watcher.emit('error', Object.assign(new Error('audit late write-settle error'), { code: 'EPERM' }))).not.toThrow()
  } finally {
    try { await ctx.fiber.dispose() } finally { await rm(root, { recursive: true, force: true }) }
  }
}, 15_000)

import { mkdtemp, mkdir, writeFile, symlink, cp, readlink, rm, stat } from 'node:fs/promises'
import { join, isAbsolute } from 'node:path'
import { tmpdir } from 'node:os'
const root = await mkdtemp(join(tmpdir(), 'dsh-audit-resource-alias-'))
try {
  const source = join(root, 'dist-exe', 'runtime', 'python', 'bin')
  const destination = join(root, 'carrier', 'runtime')
  await mkdir(source, { recursive: true })
  await writeFile(join(source, 'python3.12'), 'audit interpreter placeholder')
  await symlink('python3.12', join(source, 'python3'))
  await cp(join(root, 'dist-exe', 'runtime'), destination, { recursive: true })
  const copied = join(destination, 'python', 'bin', 'python3')
  const target = await readlink(copied)
  await rm(join(root, 'dist-exe'), { recursive: true })
  let relocatedReadable = true
  try { await stat(copied) } catch (error) { if (error.code === 'ENOENT') relocatedReadable = false; else throw error }
  console.log(JSON.stringify({ originalAlias: 'python3.12', copiedAlias: target, copiedAliasIsAbsolute: isAbsolute(target), relocatedReadable }))
} finally { await rm(root, { recursive: true, force: true }) }
